// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;

    function setUp() public { c = new XBORNID(); }

    function testFuzz_property(uint256 amount, address newOwner) public {
        // owner of c is the test contract (setUp caller); hand ownership-receiving role to a live receiver
        vm.assume(newOwner != address(0));
        amount = bound(amount, 1, 1e30);

        Receiver sink = new Receiver();
        // keep ownership with the test contract, but make sure payout goes to a receiver that accepts ETH
        vm.prank(address(this));
        c.transferOwnership(address(sink));

        vm.deal(address(c), amount);
        assertEq(address(c).balance, amount);

        vm.prank(address(sink));
        try c.withdraw() {
            // RULE: after withdraw(), the contract holds no ether; the whole balance went to the owner.
            assertTrue(address(c).balance == 0 && address(sink).balance == amount);
        } catch {
            assertTrue(false);
        }
    }
}

contract Receiver {
    receive() external payable {}
}
